'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// VARIABLES //

var mode = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( mode instanceof Error )
};


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof mode, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', opts, function test( t ) {
	var y = mode( NaN, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = mode( 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `alpha`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mode( 0.0, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( -1.0, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( NINF, 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `beta`, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = mode( 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mode( NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `0 < beta <= 1` and `alpha > 0`, the function returns `0`', opts, function test( t ) {
	var y;

	y = mode( 2.0, 0.5 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = mode( 2.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function returns the mode of a log logistic distribution', opts, function test( t ) {
	var expected;
	var alpha;
	var beta;
	var y;
	var i;

	expected = data.expected;
	alpha = data.alpha;
	beta = data.beta;
	for ( i = 0; i < alpha.length; i++ ) {
		y = mode( alpha[ i ], beta[ i ] );
		if ( y === expected[ i ] ) {
			t.strictEqual( y, expected[ i ], 'alpha: '+alpha[ i ]+', beta: '+beta[ i ]+', y: '+y+', expected: '+expected[ i ] );
		} else {
			t.strictEqual( isAlmostSameValue( y, expected[i], 1 ), true, 'within tolerance. alpha: '+alpha[i]+'. beta: '+beta[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
